export function Retry({
  taskTitle = "{{taskTitle}}",
  reason = "{{reason}}",
  attempt = {{attempt}},
  maxAttempts = {{maxAttempts}},
  status = "{{status}}",
  accent = "{{accent}}",
}) {
  const icons = {
    failed: { svg: "<svg viewBox=\"0 0 16 16\" width=\"16\" height=\"16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M4 4l8 8M12 4l-8 8\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg>", color: "#b23b3b" },
    retrying: { svg: "<svg viewBox=\"0 0 16 16\" width=\"16\" height=\"16\" fill=\"none\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"8\" r=\"6.25\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M8 4.5V8l2.5 1.5\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>", color: accent },
    exhausted: { svg: "<svg viewBox=\"0 0 16 16\" width=\"16\" height=\"16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M5 1.5h6L14.5 5v6L11 14.5H5L1.5 11V5z\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/><path d=\"M5.5 5.5l5 5M10.5 5.5l-5 5\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"/></svg>", color: "#241430" },
  };
  const active = icons[status] ?? icons.failed;
  const exhausted = status === "exhausted";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", maxWidth: 340, padding: 20, background: "#FAF7F2",
      color: "#241430", borderRadius: 14, border: "1.5px solid #24143020" }}>
      <div style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px", borderRadius: 999, background: "#24143010", marginBottom: 12 }}>
        <span style={{ color: active.color, display: "inline-flex" }} dangerouslySetInnerHTML={{ __html: active.svg }} />
        <span style={{ fontWeight: 600, fontSize: 13, textTransform: "capitalize" }}>{status}</span>
      </div>
      <h3 style={{ margin: "0 0 6px", fontSize: 17, fontWeight: 600 }}>{taskTitle}</h3>
      <p style={{ margin: "0 0 4px", fontSize: 14, color: "#241430cc" }}>{reason}</p>
      <p style={{ margin: "0 0 14px", fontSize: 13, color: "#24143099" }}>Attempt {attempt} of {maxAttempts}</p>
      <button type="button" disabled={exhausted} style={{ display: "inline-flex", alignItems: "center", gap: 6, border: "none",
        background: accent, color: "#241430", fontWeight: 600, fontSize: 13, padding: "8px 14px", borderRadius: 8,
        cursor: exhausted ? "default" : "pointer", opacity: exhausted ? 0.5 : 1 }}>
        <span dangerouslySetInnerHTML={{ __html: "<svg viewBox=\"0 0 16 16\" width=\"14\" height=\"14\" fill=\"none\" aria-hidden=\"true\"><path d=\"M13 8A5 5 0 1 1 11.5 4.5\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><path d=\"M13 2v3.5H9.5\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>" }} /> Retry now
      </button>
    </div>
  );
}
